--

CREATE TABLE `don_b` (
  `id` int(11) NOT NULL,
  `ngay_cap_nhat` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'Thời gian cập nhật gần nhất',
  `ma_san_pham` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '品番 - Mã sản phẩm',
  `so_met_quy_cach` int(11) NOT NULL DEFAULT 0 COMMENT 'Quy cách số mét/cuộn từ mã SP',
  `so_phieu_nhap` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手配No. - Số sắp xếp/tháp no',
  `ma_don_hang` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'オーダー - Mã đơn hàng (Khóa định danh check trùng)',
  `ngay_nhan_don` date DEFAULT NULL COMMENT 'Ngày nhận đơn',
  `ky_han_giao_hang` date DEFAULT NULL COMMENT 'Kỳ hạn đơn hàng',
  `ngay_yc_nhap_kho` date DEFAULT NULL COMMENT 'Kỳ hạn nhập kho / Ngày y/c nhập kho',
  `ma_khach_hang` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客先コード - Mã khách hàng',
  `ten_khach_hang` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客先 - Tên khách hàng',
  `so_luong_dat` int(11) NOT NULL DEFAULT 0 COMMENT '受注数 - Số lượng cuộn/cái đặt hàng',
  `tong_met_can` bigint(20) NOT NULL DEFAULT 0 COMMENT 'Tổng mét cần = so_met_quy_cach * so_luong_dat',
  `phuong_thuc_van_chuyen` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'SEA' COMMENT '発送方法 - SEA, AIR...',
  `phan_loai_don` enum('A','B') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'B' COMMENT 'A/B - Loại đơn',
  `ngay_du_kien_xuat` date DEFAULT NULL COMMENT 'Ngày dự kiến xuất hàng',
  `ngay_xuat_thuc_te` date DEFAULT NULL COMMENT 'Ngày xuất thực tế',
  `pc_note` text COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ghi chú của PC',
  `dun_xac_nhan` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Chưa xác định' COMMENT 'Đùn xác nhận: Chưa xác định, Xác nhận, Từ chối',
  `cuon_xac_nhan` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Chưa xác định' COMMENT 'Cuộn xác nhận: Chưa xác định, Xác nhận, Từ chối, K CÓ LÔ...',
  `san_xuat_note` text COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ghi chú sản xuất',
  `tinh_trang_nhap_kho` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Đang thực hiện' COMMENT 'Tình trạng nhập kho: Đang thực hiện, Hoàn thành, Từ chối...',
  `ngay_chuyen_b_to_a` date DEFAULT NULL COMMENT 'Ngày PC xác nhận chuyển từ B sang A',
  `cuon_da_sx` int(11) NOT NULL DEFAULT 0 COMMENT 'Cuộn đã SX - Số lượng thực tích sản xuất',
  `tong_met_da_sx` bigint(20) NOT NULL DEFAULT 0 COMMENT 'Tổng mét đã SX = so_met_quy_cach * cuon_da_sx',
  `con_thieu` int(11) NOT NULL DEFAULT 0 COMMENT 'Còn thiếu = so_luong_dat - cuon_da_sx',
  `tinh_trang_bobin` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tình trạng bobin',
  `ctsx_status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Chỉ thị sản xuất: +_có CTSX / -_chưa CTSX',
  `last_action_group` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'PC' COMMENT 'Bộ phận cập nhật gần nhất: PC, Đùn, Cuộn',
  `last_action_user` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User thao tác gần nhất',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

