  `last_sync_message` text COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nhật ký đồng bộ gần nhất',
  `last_sync_stats` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Thống kê inserted, updated, errors' CHECK (json_valid(`last_sync_stats`)),
